CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin') NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id CHAR(36) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_settings (id INT PRIMARY KEY,content JSON NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_settings_draft LIKE site_settings;
CREATE TABLE IF NOT EXISTS content_versions (id CHAR(36) PRIMARY KEY,content JSON NOT NULL,note VARCHAR(255),created_by CHAR(36),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS treatment_categories (id CHAR(36) PRIMARY KEY,name VARCHAR(255) NOT NULL,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS treatments (id CHAR(36) PRIMARY KEY,category_id CHAR(36) NULL,name VARCHAR(255) NOT NULL,description TEXT NOT NULL,price DECIMAL(10,2) NOT NULL DEFAULT 0,price_from TINYINT(1) NOT NULL DEFAULT 0,image_url TEXT NULL,featured TINYINT(1) NOT NULL DEFAULT 0,visible TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,INDEX(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS staff (id CHAR(36) PRIMARY KEY,name VARCHAR(255) NOT NULL,role VARCHAR(255) NOT NULL,bio TEXT NOT NULL,phone VARCHAR(100) NOT NULL,image_url TEXT NULL,facebook_url TEXT NULL,instagram_url TEXT NULL,visible TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS gallery_images (id CHAR(36) PRIMARY KEY,url TEXT NOT NULL,alt VARCHAR(500) NOT NULL,caption TEXT NOT NULL,visible TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS opening_hours (weekday TINYINT PRIMARY KEY,opens TIME NULL,closes TIME NULL,closed TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS special_opening_hours (id CHAR(36) PRIMARY KEY,date DATE NOT NULL,label VARCHAR(255) NOT NULL,opens TIME NULL,closes TIME NULL,closed TINYINT(1) NOT NULL DEFAULT 0,INDEX(date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
